"use client";

import * as React from "react";
import { Check, X } from "lucide-react";
import { Faces, FACES_MORPH } from "./faces";
import { NumberRoll } from "./number-roll";
import { PricingToggle } from "./pricing-toggle";
import { StatusButton, type ActionStatus } from "./status-button";
import { StepperInput } from "./stepper-input";
import { TextMorph } from "./text-morph";
import {
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * PRICING PLANS: plans that turn into their own checkout
 *
 *   plans     flat thin line cards; the featured plan is the lit
 *             surface, ruled with fine ledger fine lines. Billing
 *             toggles roll every price the way it moved
 *   choose    the plan you pick turns into its checkout in place,
 *             a slip on the same card: seats on a stepper, the
 *             line items and the total rolling as seats or billing
 *             change, while the other plans step back
 *   checkout  Continue goes Opening checkout → Redirecting through
 *             your onCheckout (create the Stripe or Paddle session
 *             there); a failure keeps the slip and says why
 *   current   with currentPlanId, buttons read Current plan,
 *             Upgrade or Downgrade, for a billing settings page
 * ───────────────────────────────────────────────────────── */

export type Billing = "monthly" | "yearly";

export interface PricingPlan {
  id: string;
  name: string;
  description?: string;
  /** Per month, in major units; per seat when perSeat. Yearly is the monthly rate when billed yearly. */
  price: { monthly: number; yearly: number };
  perSeat?: boolean;
  minSeats?: number;
  maxSeats?: number;
  features: string[];
  /** The plan on the lit surface. */
  featured?: boolean;
  /** A short tag beside the name, e.g. "Most popular". */
  badge?: string;
  /** Button label; defaults to "Get <name>", "Start free" or Upgrade / Downgrade. */
  cta?: string;
  /** A link instead of checkout, e.g. "Contact sales" for an enterprise plan. */
  href?: string;
}

export interface PricingCheckout {
  plan: PricingPlan;
  billing: Billing;
  seats: number;
  /** What's due now, in major units: a month, or a year when billed yearly. */
  total: number;
}

export interface PricingPlansProps {
  plans: PricingPlan[];
  billing?: Billing;
  defaultBilling?: Billing;
  onBillingChange?: (billing: Billing) => void;
  /** The plan the account is on, for a billing settings page. */
  currentPlanId?: string;
  /** Start checkout; resolve once you're redirecting (or done), throw an Error to show its message. */
  onCheckout?: (checkout: PricingCheckout) => Promise<unknown>;
  currency?: string;
  locale?: string;
  className?: string;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const subscribeNothing = () => () => {};
/** False on the server and while hydrating: text is formatted in one fixed locale until then, so the server's and the visitor's never disagree. */
const useHydrated = () =>
  React.useSyncExternalStore(
    subscribeNothing,
    () => true,
    () => false,
  );
const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;

/* The lit plan: --primary with a lit corner from --primary-foreground, a deeper lower edge and 1px light edges. */
const LIT_SURFACE: React.CSSProperties = {
  backgroundColor: "var(--primary)",
  backgroundImage: `radial-gradient(120% 90% at 0% 0%, ${mix("var(--primary-foreground)", 22)} 0%, transparent 55%), linear-gradient(170deg, transparent 45%, ${mix("black", 22)} 100%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 36)}, inset 0 0 0 1px ${mix("var(--primary-foreground)", 12)}`,
};
/* Its signature: fine ledger rules, fading out from the top right. */
const LEDGER: React.CSSProperties = {
  backgroundImage: `repeating-linear-gradient(180deg, transparent 0 11px, ${mix("var(--primary-foreground)", 10)} 11px 12px)`,
  maskImage: "radial-gradient(130% 80% at 100% 0%, black 0%, transparent 70%)",
  WebkitMaskImage:
    "radial-gradient(130% 80% at 100% 0%, black 0%, transparent 70%)",
};
const LIT_ACTION: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, ${mix("var(--primary-foreground)", 16)}, transparent 60%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 32)}, inset 0 0 0 1px ${mix("black", 10)}`,
};
const COLS: Record<number, string> = {
  1: "",
  2: "@[640px]:grid-cols-2",
  3: "@[640px]:grid-cols-3",
  4: "@[760px]:grid-cols-2 @[1040px]:grid-cols-4",
};

function useMoney(locale: string | undefined, currency: string) {
  return React.useMemo(() => {
    const whole = new Intl.NumberFormat(locale, {
      style: "currency",
      currency,
      maximumFractionDigits: 0,
    });
    const cents = new Intl.NumberFormat(locale, {
      style: "currency",
      currency,
    });
    return { format: (n: number) => (n % 1 ? cents : whole).format(n) };
  }, [locale, currency]);
}

const priceFormat = (
  currency: string,
  n: number,
): Intl.NumberFormatOptions => ({
  style: "currency",
  currency,
  minimumFractionDigits: n % 1 ? 2 : 0,
  maximumFractionDigits: n % 1 ? 2 : 0,
});

export function PricingPlans({
  plans,
  billing: billingProp,
  defaultBilling = "monthly",
  onBillingChange,
  currentPlanId,
  onCheckout,
  currency = "USD",
  locale,
  className = "",
}: PricingPlansProps) {
  const reduced = useInteractionReducedMotion();
  const hydrated = useHydrated();
  const money = useMoney(locale ?? (hydrated ? undefined : "en-US"), currency);
  const baseId = React.useId();
  const [ownBilling, setOwnBilling] = React.useState<Billing>(defaultBilling);
  const billing = billingProp ?? ownBilling;
  const [dir, setDir] = React.useState(1);
  const [openId, setOpenId] = React.useState<string | null>(null);
  const [seats, setSeats] = React.useState<Record<string, number>>({});
  const [status, setStatus] = React.useState<{
    id: string;
    status: ActionStatus;
    error?: string;
  } | null>(null);
  const [ready, setReady] = React.useState(false);
  const slipRefs = React.useRef(new Map<string, HTMLDivElement>());
  const ctaRefs = React.useRef(new Map<string, HTMLElement>());

  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setReady(true));
    return () => cancelAnimationFrame(frame);
  }, []);

  React.useEffect(() => {
    if (!ready || !openId) return;
    slipRefs.current.get(openId)?.focus({ preventScroll: true });
  }, [openId, ready]);

  const setBilling = (next: Billing) => {
    if (next === billing) return;
    setDir(next === "yearly" ? 1 : -1);
    if (billingProp === undefined) setOwnBilling(next);
    onBillingChange?.(next);
  };

  // The toggle's badge says what yearly saves, from the plans themselves.
  const save = Math.max(
    0,
    ...plans
      .filter((p) => p.price.monthly > 0)
      .map((p) => Math.round((1 - p.price.yearly / p.price.monthly) * 100)),
  );
  const options = React.useMemo(
    () => [
      { value: "monthly", label: "Monthly" },
      {
        value: "yearly",
        label: "Yearly",
        ...(save > 0 ? { badge: `Save ${save}%` } : {}),
      },
    ],
    [save],
  );

  const current = plans.find((p) => p.id === currentPlanId);
  const seatsOf = (p: PricingPlan) =>
    p.perSeat ? Math.max(p.minSeats ?? 1, seats[p.id] ?? p.minSeats ?? 1) : 1;
  const totalOf = (p: PricingPlan) =>
    p.price[billing] * seatsOf(p) * (billing === "yearly" ? 12 : 1);
  const busy = status?.status === "pending" || status?.status === "success";

  const close = () => {
    if (busy || !openId) return;
    const id = openId;
    setOpenId(null);
    setStatus(null);
    window.setTimeout(
      () => ctaRefs.current.get(id)?.focus({ preventScroll: true }),
      reduced ? 0 : FACES_MORPH,
    );
  };

  const checkout = async (p: PricingPlan) => {
    if (busy) return;
    setStatus({ id: p.id, status: "pending" });
    try {
      await onCheckout?.({
        plan: p,
        billing,
        seats: seatsOf(p),
        total: totalOf(p),
      });
      setStatus({ id: p.id, status: "success" });
    } catch (e) {
      setStatus({
        id: p.id,
        status: "error",
        error:
          e instanceof Error && e.message
            ? e.message
            : "Couldn’t start checkout. Try again.",
      });
    }
  };

  const ctaLabel = (p: PricingPlan) => {
    if (p.id === currentPlanId) return "Current plan";
    if (current)
      return p.price.monthly >= current.price.monthly
        ? `Upgrade to ${p.name}`
        : `Switch to ${p.name}`;
    return p.cta ?? (p.price.monthly === 0 ? "Start free" : `Get ${p.name}`);
  };

  return (
    <div
      className={`w-full ${className}`}
      onKeyDown={(e) => {
        if (e.key === "Escape" && openId) {
          e.preventDefault();
          close();
        }
      }}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 960px)" }}
      />
      <div className="@container w-full">
        <div className="flex justify-center">
          <PricingToggle
            value={billing}
            onValueChange={(v) => setBilling(v as Billing)}
            options={options}
          />
        </div>

        <ul
          className={`mt-6 grid grid-cols-1 items-stretch gap-3 ${COLS[Math.min(plans.length, 4)] ?? ""}`}
        >
          {plans.map((p) => {
            const lit = Boolean(p.featured);
            const isOpen = openId === p.id;
            const isCurrent = p.id === currentPlanId;
            const amount = p.price[billing];
            const free = p.price.monthly === 0;
            const st = status?.id === p.id ? status : null;
            const n = seatsOf(p);
            const total = totalOf(p);
            const note = free
              ? "Free forever"
              : billing === "yearly"
                ? `${money.format(amount * 12)}${p.perSeat ? " per seat" : ""} billed yearly`
                : p.perSeat
                  ? "Per seat, billed monthly"
                  : "Billed monthly";
            const muted = lit
              ? "text-primary-foreground/70"
              : "text-muted-foreground";
            const dimmed = openId !== null && !isOpen;

            return (
              <li
                key={p.id}
                className={`relative flex flex-col overflow-clip rounded-[28px] ${isOpen ? "self-start" : ""} ${lit ? "text-primary-foreground" : "border border-border bg-card text-card-foreground"}`}
                style={{
                  ...(lit ? LIT_SURFACE : {}),
                  opacity: dimmed ? 0.5 : 1,
                  transform: dimmed && !reduced ? "scale(0.985)" : "none",
                  transition: reduced
                    ? "opacity 160ms"
                    : `opacity 320ms ${EASE}, transform ${FACES_MORPH}ms ${EASE}`,
                }}
              >
                {lit && (
                  <span
                    aria-hidden="true"
                    className="pointer-events-none absolute inset-0"
                    style={LEDGER}
                  />
                )}
                <Faces
                  active={isOpen ? 1 : 0}
                  reduced={reduced}
                  ready={ready}
                  className="flex-1"
                >
                  {/* The plan. */}
                  <div className="flex h-full flex-col p-6">
                    <div className="flex items-center gap-2">
                      <h3
                        id={`${baseId}-${p.id}`}
                        className="text-[16px] font-medium tracking-[-0.01em]"
                      >
                        {p.name}
                      </h3>
                      {(p.badge || isCurrent) && (
                        <span
                          className={`rounded-full px-2 py-0.5 text-[11.5px] font-medium ${lit ? "bg-primary-foreground/15 text-primary-foreground" : "bg-primary/10 text-primary"}`}
                        >
                          {isCurrent ? "Your plan" : p.badge}
                        </span>
                      )}
                    </div>
                    {p.description && (
                      <p
                        className={`mt-1.5 text-[13.5px] leading-relaxed ${muted}`}
                      >
                        {p.description}
                      </p>
                    )}

                    <div className="mt-6 flex items-baseline gap-1.5">
                      <span className="text-[clamp(40px,7cqw,52px)] font-medium leading-none tracking-[-0.045em] tabular-nums">
                        {free ? (
                          "Free"
                        ) : (
                          <NumberRoll
                            value={amount}
                            locales={locale}
                            format={priceFormat(currency, amount)}
                          />
                        )}
                      </span>
                      {!free && (
                        <span className={`text-[13.5px] ${muted}`}>
                          {p.perSeat ? "/seat/mo" : "/mo"}
                        </span>
                      )}
                    </div>
                    <div
                      className={`relative mt-2 h-5 overflow-hidden text-[12.5px] ${muted}`}
                    >
                      <span
                        key={note}
                        className="absolute inset-0 truncate motion-safe:animate-[ui-note-in_380ms_cubic-bezier(0.23,1,0.32,1)_both]"
                        style={
                          {
                            "--ui-from": `${dir > 0 ? 100 : -100}%`,
                          } as React.CSSProperties
                        }
                      >
                        {note}
                      </span>
                    </div>

                    <div className="mt-6">
                      {p.href && !isCurrent ? (
                        <a
                          ref={(el) => {
                            if (el) ctaRefs.current.set(p.id, el);
                          }}
                          href={p.href}
                          className={`flex h-12 w-full items-center justify-center rounded-full text-[15px] font-medium ${INTERACTION_PRESS} ${INTERACTION_FOCUS} ${lit ? "bg-primary-foreground text-primary" : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent"}`}
                        >
                          {p.cta ?? "Contact sales"}
                        </a>
                      ) : free && !isCurrent ? (
                        <StatusButton
                          status={st?.status ?? "idle"}
                          labels={{
                            idle: ctaLabel(p),
                            pending: "Setting up",
                            success: "You’re in",
                            error: "Try again",
                          }}
                          variant="outline"
                          onClick={() => void checkout(p)}
                          className="h-12 w-full text-[15px]"
                        />
                      ) : (
                        <button
                          ref={(el) => {
                            if (el) ctaRefs.current.set(p.id, el);
                          }}
                          type="button"
                          disabled={isCurrent}
                          aria-expanded={isOpen}
                          onClick={() => {
                            setStatus(null);
                            setOpenId(p.id);
                          }}
                          className={`flex h-12 w-full cursor-pointer items-center justify-center rounded-full text-[15px] font-medium disabled:cursor-default ${INTERACTION_PRESS} ${INTERACTION_FOCUS} ${
                            isCurrent
                              ? lit
                                ? "bg-primary-foreground/15 text-primary-foreground/80"
                                : "bg-muted text-muted-foreground"
                              : lit
                                ? "bg-primary-foreground text-primary hover:bg-primary-foreground/90"
                                : "bg-primary text-primary-foreground hover:bg-primary/90"
                          }`}
                          style={!lit && !isCurrent ? LIT_ACTION : undefined}
                        >
                          {ctaLabel(p)}
                        </button>
                      )}
                    </div>
                    {st?.status === "error" && free && (
                      <p
                        role="alert"
                        className="mt-2 text-center text-[12.5px] text-red-600 dark:text-red-400"
                      >
                        {st.error}
                      </p>
                    )}

                    <ul
                      className={`mt-6 space-y-2.5 border-t pt-5 text-[13.5px] ${lit ? "border-primary-foreground/15" : "border-border"}`}
                    >
                      {p.features.map((f) => (
                        <li key={f} className="flex gap-2.5">
                          <span
                            className={`mt-px flex size-[18px] shrink-0 items-center justify-center rounded-full ${lit ? "bg-primary-foreground/15" : "bg-primary/10 text-primary"}`}
                          >
                            <Check
                              aria-hidden="true"
                              className="size-3"
                              strokeWidth={2.5}
                            />
                          </span>
                          <span
                            className={
                              lit
                                ? "text-primary-foreground/90"
                                : "text-foreground"
                            }
                          >
                            {f}
                          </span>
                        </li>
                      ))}
                    </ul>
                  </div>

                  {/* Its checkout: a slip on the same card. */}
                  <div className="p-2.5">
                    <div
                      ref={(el) => {
                        if (el) slipRefs.current.set(p.id, el);
                        else slipRefs.current.delete(p.id);
                      }}
                      tabIndex={-1}
                      role="group"
                      aria-label={`Checkout for ${p.name}`}
                      className="rounded-[20px] border border-border bg-card p-4 text-card-foreground outline-none"
                    >
                      <div className="flex items-center justify-between gap-3">
                        <p className="text-[15px] font-medium tracking-[-0.01em]">
                          {p.name} ·{" "}
                          <TextMorph>
                            {billing === "yearly" ? "Yearly" : "Monthly"}
                          </TextMorph>
                        </p>
                        <button
                          type="button"
                          aria-label="Back to plans"
                          onClick={close}
                          className={`-mr-1.5 flex size-8 cursor-pointer items-center justify-center rounded-full text-muted-foreground hover:bg-accent hover:text-foreground ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`}
                        >
                          <X aria-hidden="true" className="size-4" />
                        </button>
                      </div>

                      {p.perSeat && (
                        <div className="mt-4 flex items-center justify-between gap-3">
                          <span className="text-[13.5px] text-muted-foreground">
                            Seats
                          </span>
                          <StepperInput
                            label="Seats"
                            value={n}
                            onValueChange={(v) =>
                              !busy && setSeats((s) => ({ ...s, [p.id]: v }))
                            }
                            min={p.minSeats ?? 1}
                            max={p.maxSeats ?? 500}
                            size="sm"
                            disabled={busy}
                          />
                        </div>
                      )}

                      <dl className="mt-4 space-y-2 border-t border-border pt-4 text-[13.5px]">
                        <div className="flex justify-between gap-3">
                          <dt className="text-muted-foreground">
                            {money.format(amount)}
                            {p.perSeat ? " × " : ""}
                            {p.perSeat && (
                              <NumberRoll value={n} duration={500} />
                            )}
                            {p.perSeat ? (n === 1 ? " seat" : " seats") : ""}
                            {billing === "yearly" ? " × 12 months" : " a month"}
                          </dt>
                          <dd className="tabular-nums">
                            <NumberRoll
                              value={total}
                              locales={locale}
                              format={priceFormat(currency, total)}
                              duration={700}
                            />
                          </dd>
                        </div>
                        {billing === "monthly" &&
                        p.price.yearly < p.price.monthly ? (
                          <div className="flex justify-between gap-3 text-[12.5px]">
                            <dt className="text-muted-foreground">
                              Yearly saves{" "}
                              {money.format(
                                (p.price.monthly - p.price.yearly) * 12 * n,
                              )}
                            </dt>
                            <dd>
                              <button
                                type="button"
                                disabled={busy}
                                onClick={() => setBilling("yearly")}
                                className={`cursor-pointer rounded-full text-primary underline-offset-4 hover:underline disabled:cursor-default ${INTERACTION_FOCUS}`}
                              >
                                Switch
                              </button>
                            </dd>
                          </div>
                        ) : billing === "yearly" ? (
                          <div className="flex justify-between gap-3 text-[12.5px]">
                            <dt className="text-muted-foreground">You save</dt>
                            <dd className="tabular-nums text-emerald-600 dark:text-emerald-400">
                              <NumberRoll
                                value={
                                  (p.price.monthly - p.price.yearly) * 12 * n
                                }
                                locales={locale}
                                format={priceFormat(
                                  currency,
                                  (p.price.monthly - p.price.yearly) * 12 * n,
                                )}
                                duration={700}
                              />
                            </dd>
                          </div>
                        ) : null}
                      </dl>

                      <div className="mt-4 flex items-end justify-between gap-3 border-t border-border pt-4">
                        <span className="text-[13.5px] text-muted-foreground">
                          Due today
                        </span>
                        <span className="text-[32px] font-medium leading-none tracking-[-0.04em] tabular-nums">
                          <NumberRoll
                            value={total}
                            locales={locale}
                            format={priceFormat(currency, total)}
                            duration={900}
                          />
                        </span>
                      </div>

                      <StatusButton
                        status={st?.status ?? "idle"}
                        labels={{
                          idle: "Continue to checkout",
                          pending: "Opening checkout",
                          success: "Redirecting",
                          error: "Try again",
                        }}
                        onClick={() => void checkout(p)}
                        className="mt-4 h-12 w-full text-[15px]"
                        style={st?.status === "error" ? undefined : LIT_ACTION}
                      />
                      <p
                        role={st?.status === "error" ? "alert" : undefined}
                        className={`mt-2 min-h-[18px] text-center text-[12.5px] ${st?.status === "error" ? "text-red-600 dark:text-red-400" : "text-muted-foreground"}`}
                      >
                        {st?.status === "error" ? st.error : "Cancel any time."}
                      </p>
                    </div>
                  </div>
                </Faces>
              </li>
            );
          })}
        </ul>
      </div>
    </div>
  );
}

export default PricingPlans;

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * FACES: the states of one surface, in the same place
 *
 * The active face is in flow; the others are laid over it, faded
 * and nudged aside (faces before it to the left, faces after it to
 * the right), so switching reads as the surface turning to its
 * next side. The height eases between the faces' measured heights,
 * so nothing around it jumps. Used by the blocks (the wallet's
 * activity and keypad, a pricing card and its checkout, a booking's
 * times, details and confirmation).
 * ───────────────────────────────────────────────────────── */

const EASE = "cubic-bezier(0.16,1,0.3,1)";
export const FACES_MORPH = 460;

export function Faces({
  active,
  reduced,
  ready,
  className = "",
  children,
}: {
  active: number;
  reduced: boolean;
  /** False until the first paint, so the faces don't animate into place on mount. */
  ready: boolean;
  className?: string;
  children: React.ReactNode[];
}) {
  const refs = React.useRef<(HTMLDivElement | null)[]>([]);
  const [heights, setHeights] = React.useState<number[] | null>(null);
  const count = children.length;

  React.useLayoutEffect(() => {
    const els = refs.current.slice(0, count);
    const observer = new ResizeObserver(() => {
      const next = els.map((el) => el?.offsetHeight ?? 0);
      setHeights((p) =>
        p && p.length === next.length && p.every((h, i) => h === next[i])
          ? p
          : next,
      );
    });
    els.forEach((el) => el && observer.observe(el));
    return () => observer.disconnect();
  }, [count]);

  const face = (i: number): React.CSSProperties => {
    const on = i === active;
    return {
      opacity: on ? 1 : 0,
      transform:
        on || reduced ? "none" : `translateX(${i < active ? -18 : 18}px)`,
      filter: on || reduced ? "none" : "blur(4px)",
      transition: !ready
        ? "none"
        : reduced
          ? "opacity 160ms ease-out"
          : on
            ? `opacity 320ms ${EASE} 90ms, transform ${FACES_MORPH}ms ${EASE}, filter 320ms ${EASE} 90ms`
            : `opacity 140ms ease-out, transform ${FACES_MORPH}ms ${EASE}, filter 200ms ease-out`,
    };
  };

  return (
    <div
      className={`relative overflow-clip ${className}`}
      style={{
        height: heights ? heights[active] : undefined,
        transition:
          ready && !reduced ? `height ${FACES_MORPH}ms ${EASE}` : "none",
      }}
    >
      {children.map((child, i) => (
        <div
          key={i}
          ref={(el) => {
            refs.current[i] = el;
          }}
          inert={active !== i || undefined}
          aria-hidden={active !== i || undefined}
          className={
            active === i
              ? "relative"
              : "pointer-events-none absolute inset-x-0 top-0"
          }
          style={face(i)}
        >
          {child}
        </div>
      ))}
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";

/* ─────────────────────────────────────────────────────────
 * PRICING TOGGLE: monthly or yearly, and every price rolls
 *
 *   toggle   the thumb slides and resizes to the chosen option
 *            with a little give; the labels trade colour
 *   badge    "Save 20%" sits inside Yearly and lights up in
 *            your brand colour when it's chosen
 *   prices   Price rolls each figure to its new amount, and the
 *            billing line crossfades in the direction you went
 *
 * PricingToggle is the control; Price is the number. Use them
 * together across your plan columns.
 * ───────────────────────────────────────────────────────── */

export interface BillingOption {
  value: string;
  label: string;
  /** e.g. "Save 20%". */
  badge?: string;
}

export interface PricingToggleProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange"
> {
  value: string;
  onValueChange: (value: string) => void;
  options?: BillingOption[];
  label?: string;
}

export interface PriceProps extends React.HTMLAttributes<HTMLDivElement> {
  amount: number;
  currency?: string;
  /** Format in this locale everywhere. Without it, a server render and hydration use en-US and the visitor's locale takes over after mount. */
  locales?: string | string[];
  /** e.g. "/mo"; hidden for free plans. */
  period?: string;
  /** A line under the price, e.g. "$288 billed yearly". */
  note?: string;
  /** Which way the toggle moved (1 or -1), so the note slides with it. */
  direction?: number;
  /** Classes for the figure, e.g. its size. */
  numberClassName?: string;
}

const BILLING: BillingOption[] = [
  { value: "monthly", label: "Monthly" },
  { value: "yearly", label: "Yearly", badge: "Save 20%" },
];
// A little give at the end of the slide, so the thumb feels like it was thrown, not placed.
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const EASE = "cubic-bezier(0.23,1,0.32,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

export function PricingToggle({
  value,
  onValueChange,
  options = BILLING,
  label = "Billing period",
  className = "",
  ...props
}: PricingToggleProps) {
  const reduced = useReducedMotion();
  const refs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const [thumb, setThumb] = React.useState({ left: 0, width: 0, ready: false });
  const active = Math.max(
    0,
    options.findIndex((o) => o.value === value),
  );

  React.useLayoutEffect(() => {
    const measure = () => {
      const el = refs.current[active];
      if (!el) return;
      const left = el.offsetLeft;
      const width = el.offsetWidth;
      setThumb((t) =>
        t.left === left && t.width === width
          ? t
          : { left, width, ready: t.width > 0 },
      );
    };
    measure();
    const observer = new ResizeObserver(measure);
    refs.current.forEach((el) => el && observer.observe(el));
    return () => observer.disconnect();
  }, [active, options]);

  const onKeyDown = (e: React.KeyboardEvent) => {
    if (e.key !== "ArrowRight" && e.key !== "ArrowLeft") return;
    e.preventDefault();
    const next =
      (active + (e.key === "ArrowRight" ? 1 : -1) + options.length) %
      options.length;
    onValueChange(options[next].value);
    refs.current[next]?.focus();
  };

  return (
    <div
      role="radiogroup"
      aria-label={label}
      onKeyDown={onKeyDown}
      className={`relative inline-flex items-center rounded-full border border-border bg-muted/60 p-1 ${className}`}
      {...props}
    >
      <span
        aria-hidden="true"
        className="absolute inset-y-1 left-0 rounded-full bg-background shadow-[0_0_0_1px_var(--border)]"
        style={{
          width: thumb.width,
          transform: `translateX(${thumb.left}px)`,
          transition:
            thumb.ready && !reduced
              ? `transform 520ms ${THROW}, width 420ms ${EASE}`
              : "none",
        }}
      />
      {options.map((option, i) => {
        const selected = i === active;
        return (
          <button
            key={option.value}
            ref={(el) => {
              refs.current[i] = el;
            }}
            type="button"
            role="radio"
            aria-checked={selected}
            tabIndex={selected ? 0 : -1}
            onClick={() => onValueChange(option.value)}
            className={`cursor-pointer relative flex h-8 items-center gap-2 rounded-full px-3.5 text-[13px] font-medium transition-colors duration-300 ${FOCUS} ${
              selected
                ? "text-foreground"
                : "text-muted-foreground hover:text-foreground"
            }`}
          >
            {option.label}
            {option.badge && (
              <span
                className={`rounded-full px-1.5 py-px text-[11px] font-medium transition-[background-color,color] duration-300 ${
                  selected
                    ? "bg-primary text-primary-foreground"
                    : "bg-primary/10 text-primary"
                }`}
              >
                {option.badge}
              </span>
            )}
          </button>
        );
      })}
    </div>
  );
}

export function Price({
  amount,
  currency = "USD",
  locales,
  period = "/mo",
  note,
  direction = 1,
  numberClassName = "text-[40px] font-medium leading-[1.15] tracking-[-0.03em] text-foreground",
  className = "",
  ...props
}: PriceProps) {
  const format = React.useMemo<Intl.NumberFormatOptions>(
    () => ({
      style: "currency",
      currency,
      maximumFractionDigits: amount % 1 ? 2 : 0,
      minimumFractionDigits: amount % 1 ? 2 : 0,
    }),
    [currency, amount],
  );
  return (
    <div className={className} {...props}>
      <div className="flex items-baseline gap-1">
        <NumberRoll
          value={amount}
          format={format}
          locales={locales}
          className={numberClassName}
        />
        {amount > 0 && period && (
          <span className="text-[14px] text-muted-foreground">{period}</span>
        )}
      </div>
      {note !== undefined && (
        <div className="relative mt-1 h-5 overflow-hidden text-[12.5px] text-muted-foreground">
          <span
            key={note}
            className="absolute inset-0 truncate motion-safe:animate-[ui-note-in_380ms_cubic-bezier(0.23,1,0.32,1)_both]"
            style={
              {
                "--ui-from": `${direction > 0 ? 100 : -100}%`,
              } as React.CSSProperties
            }
          >
            {note}
          </span>
        </div>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * STATUS BUTTON: a button that tells you what happened
 *
 *   idle     "Save", with an optional icon
 *   pending  a spinner opens in; the label morphs to "Saving"
 *   success  a check draws itself; "Saved"
 *   error    the button gives a small shake; "Try again"
 *
 * Every change is one motion: the icon slot opens and closes,
 * icons swap through a blur, letters the labels share stay put
 * and the button's width eases to fit.
 * ───────────────────────────────────────────────────────── */

export type ActionStatus = "idle" | "pending" | "success" | "error";

export interface StatusButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  status?: ActionStatus;
  /** Labels per state; defaults to Save, Saving, Saved, Try again. */
  labels?: Partial<Record<ActionStatus, string>>;
  /** Shown before the label while idle. */
  icon?: React.ReactNode;
  variant?: "primary" | "outline" | "ghost";
  /** "sm" is 28px tall, for toolbars and headers. */
  size?: "default" | "sm";
  /** Called this long after success (ms), e.g. to go back to idle. */
  onReset?: () => void;
  resetAfter?: number;
}

const LABELS: Record<ActionStatus, string> = {
  idle: "Save",
  pending: "Saving",
  success: "Saved",
  error: "Try again",
};
const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Check({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${EASE} 120ms`
              : "none",
        }}
      />
    </svg>
  );
}

function Alert() {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      <path
        d="M8 4.75v3.75"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinecap="round"
      />
      <circle cx="8" cy="11" r="1" fill="currentColor" />
    </svg>
  );
}

export function StatusButton({
  status = "idle",
  labels,
  icon,
  variant = "primary",
  size = "default",
  onReset,
  resetAfter = 1800,
  className = "",
  onClick,
  ...props
}: StatusButtonProps) {
  const reduced = useReducedMotion();
  const ref = React.useRef<HTMLButtonElement>(null);
  const label = { ...LABELS, ...labels }[status];
  const showIcon = status !== "idle" || Boolean(icon);
  const busy = status === "pending";
  const sm = size === "sm";
  const iconSize = sm ? 14 : 16;

  // A short shake when it fails: the eye catches it even if you looked away.
  React.useEffect(() => {
    if (status !== "error" || reduced) return;
    ref.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [status, reduced]);

  React.useEffect(() => {
    if (status !== "success" || !onReset) return;
    const timer = window.setTimeout(onReset, resetAfter);
    return () => window.clearTimeout(timer);
  }, [status, onReset, resetAfter]);

  const tone =
    status === "error"
      ? "bg-red-500/10 text-red-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_30%,transparent)] dark:text-red-400"
      : variant === "primary"
        ? "bg-primary text-primary-foreground hover:bg-primary/90"
        : variant === "ghost"
          ? `hover:bg-accent hover:text-foreground ${status === "idle" ? "text-muted-foreground" : "text-foreground"}`
          : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent";

  const icons: Record<ActionStatus, React.ReactNode> = {
    idle: icon,
    // Spins only while pending, so a hidden spinner never keeps the page busy.
    pending: (
      <span
        className={`${sm ? "size-3" : "size-3.5"} rounded-full border-[1.5px] border-current border-t-transparent opacity-80 motion-reduce:animate-none ${status === "pending" ? "animate-spin" : ""}`}
      />
    ),
    success: <Check drawn={status === "success"} reduced={reduced} />,
    error: <Alert />,
  };

  return (
    <>
      <button
        ref={ref}
        type="button"
        aria-busy={busy || undefined}
        aria-disabled={busy || undefined}
        onClick={(e) => {
          if (busy) return e.preventDefault();
          onClick?.(e);
        }}
        className={`cursor-pointer disabled:cursor-default aria-disabled:cursor-default inline-flex items-center justify-center whitespace-nowrap rounded-full font-medium transition-[background-color,color,box-shadow,scale,padding] duration-300 active:scale-[0.97] motion-reduce:active:scale-100 ${
          sm
            ? `h-7 text-[12px] ${variant === "ghost" ? "px-2.5" : "px-3"}`
            : "h-9 px-4 text-[13px]"
        } ${FOCUS} ${tone} ${className}`}
        {...props}
      >
        <span
          aria-hidden="true"
          className={`relative flex shrink-0 items-center justify-center ${sm ? "h-3.5 [&_svg]:size-3.5" : "h-4 [&_svg]:size-4"}`}
          style={{
            width: showIcon ? iconSize : 0,
            marginRight: showIcon ? (sm ? 5 : 6) : 0,
            transition: reduced
              ? "none"
              : `width 380ms ${EASE}, margin 380ms ${EASE}`,
          }}
        >
          {(Object.keys(icons) as ActionStatus[]).map((s) => (
            <span
              key={s}
              className="absolute inset-0 flex items-center justify-center"
              style={{
                opacity: s === status ? 1 : 0,
                transform: s === status ? "none" : "scale(0.6)",
                filter: s === status ? "none" : "blur(3px)",
                transition: reduced
                  ? "none"
                  : `opacity 260ms ${EASE}, transform 380ms ${EASE}, filter 260ms ${EASE}`,
              }}
            >
              {icons[s]}
            </span>
          ))}
        </span>
        <TextMorph>{label}</TextMorph>
      </button>
      {/* Outside the button, so the announcement isn't read as part of its name. */}
      <span className="sr-only" role="status">
        {status === "idle" ? "" : label}
      </span>
    </>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";

/* ─────────────────────────────────────────────────────────
 * STEPPER INPUT: a tactile number control with acceleration
 *
 *   single tap   increments or decrements by step, rolling
 *                the odometer in the direction of travel
 *   holding      waits 300ms, then accelerates smoothly from
 *                100ms down to 30ms intervals with scaled steps
 *   boundary     hitting min or max bounds disables the action
 *                and gives the container an elastic bumper shake
 *   direct edit  clicking the number reveals an exact input,
 *                committing on blur or Enter, cancelling on Escape
 * ───────────────────────────────────────────────────────── */

export interface StepperInputProps {
  /** Accessible label, e.g. "Team seats" or "Border radius". */
  label: string;
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  min?: number;
  max?: number;
  step?: number;
  /** Large step for PageUp/PageDown and prolonged acceleration. Defaults to step * 10. */
  largeStep?: number;
  /** Optional unit appended to the number, e.g. "px", "%", "seats". */
  unit?: string;
  /** Format options passed to NumberRoll when not editing. */
  format?: Intl.NumberFormatOptions;
  /** Visual variant: "pill" for rounded-full, "field" for standard form input. */
  variant?: "pill" | "field";
  size?: "sm" | "default";
  disabled?: boolean;
  name?: string;
  className?: string;
}

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function MinusIcon({ className = "size-3.5" }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
      className={className}
    >
      <path
        d="M3.5 8h9"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
      />
    </svg>
  );
}

function PlusIcon({ className = "size-3.5" }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
      className={className}
    >
      <path
        d="M8 3.5v9M3.5 8h9"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
      />
    </svg>
  );
}

const shake = (el: HTMLElement | null, reduced: boolean) => {
  if (!el || reduced) return;
  el.animate(
    [
      { transform: "none" },
      { transform: "translateX(-3px)" },
      { transform: "translateX(3px)" },
      { transform: "translateX(-1.5px)" },
      { transform: "none" },
    ],
    { duration: 280, easing: "ease-out", composite: "add" },
  );
};

export function StepperInput({
  label,
  value: controlledValue,
  defaultValue = 0,
  onValueChange,
  min = -Infinity,
  max = Infinity,
  step = 1,
  largeStep,
  unit,
  format,
  variant = "pill",
  size = "default",
  disabled = false,
  name,
  className = "",
}: StepperInputProps) {
  const reduced = useReducedMotion();
  const [uncontrolledValue, setUncontrolledValue] =
    React.useState(defaultValue);
  const isControlled = controlledValue !== undefined;
  const currentVal = isControlled ? controlledValue : uncontrolledValue;

  const [editing, setEditing] = React.useState(false);
  const [editText, setEditText] = React.useState(String(currentVal));

  const rootRef = React.useRef<HTMLDivElement>(null);
  const inputRef = React.useRef<HTMLInputElement>(null);
  const holdTimerRef = React.useRef<number | null>(null);
  const holdIntervalRef = React.useRef<number | null>(null);
  const holdStartRef = React.useRef<number>(0);

  const effectiveLargeStep = largeStep ?? step * 10;
  const atMin = currentVal <= min;
  const atMax = currentVal >= max;

  const clamp = React.useCallback(
    (n: number) => {
      let rounded = Math.round(n / step) * step;
      // Fix floating point precision, e.g. 0.1 + 0.2
      const stepDecimals = (step.toString().split(".")[1] || "").length;
      if (stepDecimals > 0) {
        rounded = Number(rounded.toFixed(stepDecimals));
      }
      return Math.min(max, Math.max(min, rounded));
    },
    [min, max, step],
  );

  const updateVal = React.useCallback(
    (nextRaw: number) => {
      const next = clamp(nextRaw);
      if (next === currentVal) {
        shake(rootRef.current, reduced);
        return false;
      }
      if (!isControlled) {
        setUncontrolledValue(next);
      }
      onValueChange?.(next);
      return true;
    },
    [clamp, currentVal, isControlled, onValueChange, reduced],
  );

  const stopHold = React.useCallback(() => {
    if (holdTimerRef.current !== null) {
      window.clearTimeout(holdTimerRef.current);
      holdTimerRef.current = null;
    }
    if (holdIntervalRef.current !== null) {
      window.clearInterval(holdIntervalRef.current);
      holdIntervalRef.current = null;
    }
  }, []);

  const stepDelta = React.useCallback(
    (dir: 1 | -1, multiplier = 1) => {
      const delta = step * multiplier * dir;
      return updateVal(currentVal + delta);
    },
    [currentVal, step, updateVal],
  );

  const startHold = React.useCallback(
    (dir: 1 | -1) => {
      if (disabled) return;
      stopHold();

      // Immediate first step
      const canMove = stepDelta(dir, 1);
      if (!canMove) return;

      holdStartRef.current = Date.now();

      // 300ms initial pause before rapid firing
      holdTimerRef.current = window.setTimeout(() => {
        const tick = () => {
          const elapsed = Date.now() - holdStartRef.current;
          let mult = 1;
          let intervalTime = 90;

          if (elapsed > 2400) {
            mult = Math.max(1, Math.round(effectiveLargeStep / step));
            intervalTime = 30;
          } else if (elapsed > 1200) {
            mult = Math.max(1, Math.round(effectiveLargeStep / step / 2));
            intervalTime = 55;
          }

          const ok = stepDelta(dir, mult);
          if (!ok) {
            stopHold();
            return;
          }

          holdIntervalRef.current = window.setTimeout(tick, intervalTime);
        };
        tick();
      }, 300);
    },
    [disabled, effectiveLargeStep, step, stepDelta, stopHold],
  );

  React.useEffect(() => {
    return () => stopHold();
  }, [stopHold]);

  const commitEdit = React.useCallback(() => {
    setEditing(false);
    const parsed = parseFloat(editText);
    if (!Number.isNaN(parsed)) {
      updateVal(parsed);
    } else {
      setEditText(String(currentVal));
    }
  }, [currentVal, editText, updateVal]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (disabled) return;

    if (e.key === "ArrowUp") {
      e.preventDefault();
      stepDelta(1, 1);
    } else if (e.key === "ArrowDown") {
      e.preventDefault();
      stepDelta(-1, 1);
    } else if (e.key === "PageUp") {
      e.preventDefault();
      updateVal(currentVal + effectiveLargeStep);
    } else if (e.key === "PageDown") {
      e.preventDefault();
      updateVal(currentVal - effectiveLargeStep);
    } else if (e.key === "Home" && min !== -Infinity) {
      e.preventDefault();
      updateVal(min);
    } else if (e.key === "End" && max !== Infinity) {
      e.preventDefault();
      updateVal(max);
    } else if (editing) {
      if (e.key === "Enter") {
        e.preventDefault();
        commitEdit();
      } else if (e.key === "Escape") {
        e.preventDefault();
        setEditing(false);
        setEditText(String(currentVal));
      }
    }
  };

  const isSmall = size === "sm";
  const hCls = isSmall ? "h-7" : "h-9";
  const btnW = isSmall ? "w-7" : "w-8";
  const roundedCls = variant === "pill" ? "rounded-full" : "rounded-lg";

  return (
    <div
      ref={rootRef}
      role="group"
      aria-label={label}
      tabIndex={disabled ? -1 : 0}
      onKeyDown={handleKeyDown}
      className={`inline-flex ${hCls} items-center border border-border bg-background p-0.5 select-none ${roundedCls} transition-[box-shadow,border-color] duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 ${disabled ? "opacity-50 pointer-events-none" : ""} ${className}`}
      style={{
        boxShadow: "0 0 0 1px transparent",
      }}
    >
      {/* Hidden input for HTML form submissions */}
      {name && <input type="hidden" name={name} value={currentVal} />}

      {/* Decrement Button */}
      <button
        type="button"
        tabIndex={-1}
        aria-label={`Decrease ${label}`}
        disabled={disabled || atMin}
        onPointerDown={(e) => {
          if (e.pointerType === "mouse" && e.button !== 0) return;
          try {
            e.currentTarget.setPointerCapture(e.pointerId);
          } catch {}
          startHold(-1);
        }}
        onPointerUp={(e) => {
          try {
            if (e.currentTarget.hasPointerCapture(e.pointerId)) {
              e.currentTarget.releasePointerCapture(e.pointerId);
            }
          } catch {}
          stopHold();
        }}
        onPointerCancel={stopHold}
        className={`flex ${btnW} h-full items-center justify-center ${variant === "pill" ? "rounded-full" : "rounded-md"} text-muted-foreground transition-colors hover:bg-muted hover:text-foreground active:scale-95 disabled:pointer-events-none disabled:opacity-30 cursor-pointer disabled:cursor-default touch-manipulation`}
      >
        <MinusIcon />
      </button>

      {/* Value Display / Direct Edit */}
      <div
        className="relative flex min-w-[3.25rem] flex-1 items-center justify-center px-2 font-mono text-[13px] tabular-nums text-foreground cursor-text"
        onClick={() => {
          if (disabled || editing) return;
          setEditing(true);
          setEditText(String(currentVal));
          setTimeout(() => inputRef.current?.select(), 10);
        }}
      >
        {editing ? (
          <input
            ref={inputRef}
            type="text"
            inputMode="numeric"
            value={editText}
            onChange={(e) => setEditText(e.target.value)}
            onBlur={commitEdit}
            className="w-full bg-transparent text-center font-mono text-[13px] text-foreground outline-none [appearance:textfield] [&::-webkit-inner-spin-button]:appearance-none [&::-webkit-outer-spin-button]:appearance-none"
            autoFocus
          />
        ) : (
          <div className="flex items-baseline gap-1" aria-hidden="true">
            <NumberRoll value={currentVal} format={format} duration={260} />
            {unit && (
              <span className="font-sans text-[11px] text-muted-foreground">
                {unit}
              </span>
            )}
          </div>
        )}

        {/* Screen reader live value */}
        <span className="sr-only" role="status" aria-live="polite">
          {label}: {currentVal} {unit ?? ""}
        </span>
      </div>

      {/* Increment Button */}
      <button
        type="button"
        tabIndex={-1}
        aria-label={`Increase ${label}`}
        disabled={disabled || atMax}
        onPointerDown={(e) => {
          if (e.pointerType === "mouse" && e.button !== 0) return;
          try {
            e.currentTarget.setPointerCapture(e.pointerId);
          } catch {}
          startHold(1);
        }}
        onPointerUp={(e) => {
          try {
            if (e.currentTarget.hasPointerCapture(e.pointerId)) {
              e.currentTarget.releasePointerCapture(e.pointerId);
            }
          } catch {}
          stopHold();
        }}
        onPointerCancel={stopHold}
        className={`flex ${btnW} h-full items-center justify-center ${variant === "pill" ? "rounded-full" : "rounded-md"} text-muted-foreground transition-colors hover:bg-muted hover:text-foreground active:scale-95 disabled:pointer-events-none disabled:opacity-30 cursor-pointer disabled:cursor-default touch-manipulation`}
      >
        <PlusIcon />
      </button>
    </div>
  );
}

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
/** Thrown things (indicators, thumbs): a slight overshoot on transform only. */
export const EASE_THROW = "cubic-bezier(0.34, 1.36, 0.64, 1)";
/**
 * The press every button primitive shares: a 3% give that eases in and settles back.
 * Tailwind v4's scale-* writes the `scale` property, so `scale` has to be in the list
 * or the press snaps.
 */
export const INTERACTION_PRESS =
  "transition-[background-color,color,box-shadow,opacity,scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** Smooth Apple/rational rubber-band curve: continuous exponential-like resistance without linear kinks. */
export function rubberBand(
  overshoot: number,
  dimension = 320,
  constant = 0.55,
): number {
  const d = dimension || 320;
  const abs = Math.abs(overshoot);
  return Math.sign(overshoot) * (1 - 1 / ((abs * constant) / d + 1)) * d;
}

/** Projects resting travel from release velocity (velocity in px/ms; time in seconds). */
export function projectInertia(
  distance: number,
  velocity: number,
  time = 0.12,
): number {
  return distance + velocity * 1000 * time;
}

/** Smooths incoming release velocity toward a boundary so springs don't slam or clip into walls. */
export function softenVelocity(
  velocity: number,
  distanceToTarget: number,
  factor = 10,
): number {
  const maxAllowed = Math.abs(distanceToTarget) * factor;
  return Math.sign(velocity) * Math.min(Math.abs(velocity), maxAllowed);
}

/** A damped spring sampled by WAAPI: tuned for organic lightness with a hint of life (3% breath). */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 480,
  config: { omega?: number; damping?: number; steps?: number } = {},
) {
  const { omega = 16, damping = 0.74, steps = 36 } = config;
  const damped = omega * Math.sqrt(Math.max(0.001, 1 - damping * damping));
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: steps + 1 }, (_, i) => {
    const t = (i / steps) * (duration / 1000);
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === steps ? to : value, offset: i / steps };
  });
}

